#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-only
"""Stage only verified release artifacts and generate EN/DE installation pages."""
import hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parent;REPO=ROOT.parent
v=json.loads((ROOT/'build/release.json').read_text());apk=ROOT/'build'/v['file']
assert v['sha256']==hashlib.sha256(apk.read_bytes()).hexdigest()
assert v['signerSha256']==(ROOT/'signer-sha256.txt').read_text().strip()
assert v['debuggable'] is False
out=REPO/'website/downloads';out.mkdir(exist_ok=True)
for name in [v['file'],v['file']+'.sha256','release.json']:shutil.copy2(ROOT/'build'/name,out/name)
for de in (False,True):
    t=lambda a,b:a if de else b
    folder=REPO/'website'/('de/android' if de else 'android');folder.mkdir(parents=True,exist_ok=True)
    title=t('Hauser für Android','Hauser for Android')
    html=f'''<!doctype html>
<!-- SPDX-License-Identifier: AGPL-3.0-only -->
<html lang="{'de' if de else 'en'}" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{t('Signierte Hauser-APK für Android 11 und neuer. Kostenlos, für deinen eigenen Hauser-Server.','Signed Hauser APK for Android 11 and newer. Free, for your own Hauser server.')}"><link rel="canonical" href="https://hauserhome.app/{'de/' if de else ''}android/"><link rel="alternate" hreflang="en" href="https://hauserhome.app/android/"><link rel="alternate" hreflang="de" href="https://hauserhome.app/de/android/"><link rel="stylesheet" href="/design-tokens/tokens.css"><link rel="stylesheet" href="/android/download.css"></head>
<body><main><a href="/{'de/' if de else ''}"><img src="/brand/hauser-logo-dark.svg" width="139" height="48" alt="Hauser"></a><p class="eyebrow">ANDROID · PUBLIC BETA</p><h1>{title}</h1><p>{t('Dein Zuhause auf Telefon und Tablet. Die App zeigt die bestehende Weboberfläche deines eigenen Hauser-Servers. Kostenlos. Kein Hauser-Abo.','Your home on phone and tablet. The app shows the existing web interface from your own Hauser server. Free. No Hauser subscription.')}</p><p><a class="download" href="/downloads/{v['file']}" download>{t('Signierte APK herunterladen','Download signed APK')} · {v['name']}</a></p><p>{t('Android 11 oder neuer · aktuelle Android System WebView ·','Android 11 or newer · up-to-date Android System WebView ·')} {v['bytes']/1048576:.2f} MiB · {t('VersionCode','Version code')} {v['code']}</p>
<h2>{t('Einrichten','Set up')}</h2><ol><li>{t('Installiere zuerst Hauser für dein vorhandenes Home Assistant. Apple Home wird unter Android nicht angeboten.','First install Hauser for your existing Home Assistant. Apple Home is not available on Android.')}</li><li>{t('Öffne die APK. Erlaube bei Bedarf nur deinem Browser oder Dateimanager die Installation dieser App. Schalte diese Erlaubnis danach wieder aus. Play Protect bleibt an.','Open the APK. If asked, allow this installation from your browser or file manager, then turn that permission off again. Keep Play Protect enabled.')}</li><li>{t('Öffne Hauser, tippe „Licht an“ und wähle Home Assistant. Öffne am Hauser-Server System → Telefon koppeln. Fotografiere den QR-Code oder gib Hauser-Adresse und Code von Hand ein.','Open Hauser, tap “Lights on” and choose Home Assistant. On your Hauser server, open System → Pair a phone. Photograph the QR code or enter the Hauser address and code manually.')}</li><li>{t('Kopple im vertrauenswürdigen Heimnetz. Die App kann dich danach optional einer Person zuordnen.','Pair on your trusted home network. You can then optionally choose your resident identity.')}</li></ol>
<h2>{t('Updates und Verbindungen','Updates and connections')}</h2><p>{t('Lade die nächste APK hier herunter und installiere sie über die vorhandene App. Nicht deinstallieren: So bleibt deine Kopplung erhalten. Es gibt keine automatischen Updates und keinen Store-Release.','Download the next APK here and install over the existing app. Do not uninstall: that preserves pairing. There are no automatic updates and this is not a store release.')}</p><p>{t('Du brauchst einen erreichbaren eigenen Hauser-Server. HTTP ist nach Bestätigung nur für das vertrauenswürdige Heimnetz vorgesehen. HTTPS prüft Zertifikate vollständig. Fernzugriff benötigt Hauser 0.50.3 oder neuer mit der WebView-Sitzung sowie einen Zugang, der Gerätetokens und WebSockets zulässt. Vorgeschaltete Access-Anmeldungen werden nicht umgangen.','You need your own reachable Hauser server. HTTP requires confirmation and is for trusted private networks only. HTTPS validates certificates fully. Remote access requires Hauser 0.50.3 or newer with the WebView session and a route that accepts device tokens and WebSockets. Upstream Access logins are not bypassed.')}</p><p>{t('Android Zurück öffnet am Anfang der Weboberfläche das App-Menü mit Neu laden, Verbindung ändern und Vollbild. Die Xiaomi-Griffkorrektur ist standardmäßig aus.','Android Back at the root of the web interface opens the app menu with Reload, Change connection and Fullscreen. Xiaomi handle spacing is off by default.')}</p>
<h2>{t('Download prüfen','Verify the download')}</h2><p>SHA-256 (APK): <code>{v['sha256']}</code></p><p>{t('Signaturzertifikat SHA-256','Signing certificate SHA-256')}: <code>{v['signerSha256']}</code></p><p><a href="/downloads/{v['file']}.sha256">SHA-256</a> · <a href="/downloads/release.json">{t('Versionsdaten','Version metadata')}</a> · <a href="https://github.com/ralleur/hauser/tree/android-v{v['name']}/android">{t('Quellcode und Details','Source and details')}</a></p><p class="small">{t('Öffentliche Beta. Funktionen kommen vom konfigurierten Server. Keine Telemetrie. Code: AGPL-3.0-only. Hauser-Marke vorbehalten.','Public beta. Features come from your configured server. No analytics. Code: AGPL-3.0-only. Hauser branding reserved.')}</p><p><a href="/{'android/' if de else 'de/android/'}">{'English' if de else 'Deutsch'}</a> · <a href="/docs/getting-started/requirements/">{t('Server einrichten (EN)','Server requirements')}</a></p></main></body></html>'''
    (folder/'index.html').write_text(html)
(REPO/'website/android/download.css').write_text('''/* SPDX-License-Identifier: AGPL-3.0-only */
@font-face{font-family:'Alegreya Sans';src:url('/fonts/AlegreyaSans-Regular-subset.woff2')}@font-face{font-family:Alegreya;src:url('/fonts/Alegreya-subset.woff2')}*{box-sizing:border-box}body{background:var(--color-surface-0);color:var(--color-text-primary);font:var(--text-base)/var(--leading-relaxed) var(--font-family);margin:0}main{max-width:760px;margin:auto;padding:var(--space-7) var(--space-5)}h1,h2{font-family:var(--font-family-display);font-weight:400;line-height:var(--leading-tight)}h1{font-size:var(--text-3xl)}h2{font-size:var(--text-xl);margin-top:var(--space-7)}a{color:var(--color-accent-warm)}.download{display:inline-block;background:var(--color-accent-warm);color:var(--color-text-on-accent);padding:var(--space-4) var(--space-5);border-radius:var(--radius-lg);font-weight:600;text-decoration:none}.eyebrow,.small{font-size:var(--text-sm);color:var(--color-text-secondary)}code{overflow-wrap:anywhere;font-size:var(--text-sm)}li{margin-bottom:var(--space-3)}:focus-visible{outline:2px solid var(--color-accent-warm);outline-offset:var(--space-1)}
''')
print('android_release_staged='+v['name'])
